                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    # -----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    # Start Animation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    # -----------------------------
